CREATE FUNCTION public.sandy_tenant_content_schema_sha256() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
WITH selected AS(SELECT item,t.ordinality,n.oid AS ns,c.oid,c.relowner,c.relrowsecurity,c.relforcerowsecurity,c.relkind FROM jsonb_array_elements(public.sandy_tenant_content_manifest_v1()->'tables') WITH ORDINALITY t(item,ordinality) JOIN pg_namespace n ON n.nspname='public' JOIN pg_class c ON c.relnamespace=n.oid AND c.relname=t.item->>'table'),document AS(SELECT jsonb_agg(jsonb_build_object('table',s.item->>'table','owner',pg_get_userbyid(s.relowner),'kind',s.relkind,'rls',s.relrowsecurity,'force_rls',s.relforcerowsecurity,'columns',(SELECT jsonb_agg(jsonb_build_object('name',expected.item->>'name','type',format_type(a.atttypid,a.atttypmod),'nullable',NOT a.attnotnull,'generated',a.attgenerated,'identity',a.attidentity,'expression',CASE WHEN a.attgenerated<>'' THEN pg_get_expr(d.adbin,d.adrelid) ELSE NULL END) ORDER BY expected.ordinality) FROM jsonb_array_elements(s.item->'columns') WITH ORDINALITY expected(item,ordinality) LEFT JOIN pg_attribute a ON a.attrelid=s.oid AND a.attname=expected.item->>'name' AND a.attnum>0 AND NOT a.attisdropped LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum)) ORDER BY s.ordinality) value FROM selected s) SELECT encode(extensions.digest(value::text,'sha256'),'hex') FROM document
$$;
CREATE FUNCTION public.sandy_tenant_content_capture_v1(p_tenant uuid) RETURNS SETOF jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET timezone='UTC' AS $$
DECLARE manifest jsonb:=public.sandy_tenant_content_manifest_v1();entry jsonb;col jsonb;projection text;size_sql text;query text;row_data record;stream_buffer text;row_text text;row_chain text;sequence_number integer:=0;table_sequence integer;table_rows integer;row_count integer;owner_predicate text;order_sql text;total_bytes bigint:=0;oversize boolean;
BEGIN
 IF p_tenant IS NULL OR public.sandy_tenant_content_schema_sha256() IS DISTINCT FROM manifest->>'schema_sha256' THEN RAISE EXCEPTION 'tenant_content_schema_changed';END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(manifest->'tables') LOOP
  IF entry->>'ownership_adapter'='support_case_customer' AND entry->>'table'='sandy_product_support_comments' THEN owner_predicate:='EXISTS(SELECT 1 FROM public.sandy_product_support_cases parent WHERE parent.id=t.case_id AND parent.customer_id=$1)'; ELSE owner_predicate:=format('t.%I=$1',entry->>'owner_column');END IF;
  SELECT string_agg(format('t.%I%s',k.value,CASE WHEN EXISTS(SELECT 1 FROM jsonb_array_elements(entry->'columns')c WHERE c->>'name'=k.value AND c->>'type'='text') THEN ' COLLATE "C"' ELSE '' END),',' ORDER BY k.position) INTO order_sql FROM jsonb_array_elements_text(entry->'order') WITH ORDINALITY k(value,position);
  EXECUTE format('SELECT count(*) FROM(SELECT 1 FROM public.%I t WHERE %s LIMIT 50001)q',entry->>'table',owner_predicate) INTO row_count USING p_tenant;
  IF row_count>50000 THEN RAISE EXCEPTION 'tenant_content_table_row_bound_exceeded';END IF;
  projection:='';size_sql:='';
  FOR col IN SELECT value FROM jsonb_array_elements(entry->'columns') LOOP
   projection:=projection||CASE WHEN projection='' THEN '' ELSE ',' END||format('%L,t.%I',col->>'name',col->>'name');
   size_sql:=size_sql||CASE WHEN size_sql='' THEN '' ELSE '+' END||format('coalesce(octet_length(t.%I::text),0)',col->>'name');
  END LOOP;
  -- Bound source field bytes before building a potentially large JSON row.
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I t WHERE (%s) AND (%s)>16777216)',entry->>'table',owner_predicate,size_sql) INTO oversize USING p_tenant;
  IF oversize THEN RAISE EXCEPTION 'tenant_content_row_byte_bound_exceeded';END IF;
  IF entry->>'table'='sandy_product_graph_drafts' THEN
   IF EXISTS(SELECT 1 FROM public.sandy_product_graph_drafts draft LEFT JOIN public.email_messages message ON message.id=draft.source_message_id AND message.customer_id=p_tenant WHERE draft.customer_id=p_tenant AND draft.source_message_id IS NOT NULL AND message.id IS NULL) THEN RAISE EXCEPTION 'tenant_content_draft_source_ownership_refused';END IF;
   IF EXISTS(SELECT 1 FROM public.sandy_product_graph_drafts draft WHERE draft.customer_id=p_tenant AND CASE WHEN jsonb_typeof(draft.recipients)='array' THEN jsonb_array_length(draft.recipients)>21 ELSE true END) THEN RAISE EXCEPTION 'tenant_content_draft_recipients_projection_refused';END IF;
   IF EXISTS(SELECT 1 FROM public.sandy_product_graph_drafts draft CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN draft.customer_id=p_tenant AND jsonb_typeof(draft.recipients)='array' THEN draft.recipients ELSE '[]'::jsonb END) recipient(value) WHERE draft.customer_id=p_tenant AND (jsonb_typeof(recipient.value)<>'string' OR char_length(recipient.value#>>'{}')>254)) THEN RAISE EXCEPTION 'tenant_content_draft_recipients_projection_refused';END IF;
  END IF;
  query:=format('SELECT jsonb_build_object(%s)::text AS value FROM public.%I t WHERE %s ORDER BY %s',projection,entry->>'table',owner_predicate,order_sql);
  stream_buffer:='';table_sequence:=0;table_rows:=0;row_chain:=encode(extensions.digest(manifest->>'manifest_sha256'||':'||(entry->>'table'),'sha256'),'hex');
  FOR row_data IN EXECUTE query USING p_tenant LOOP
   row_text:=row_data.value||E'\n';
   IF octet_length(row_text)>16777216 THEN RAISE EXCEPTION 'tenant_content_row_byte_bound_exceeded';END IF;
   total_bytes:=total_bytes+octet_length(row_text);table_rows:=table_rows+1;
   IF total_bytes>134217728 OR table_rows>50000 THEN RAISE EXCEPTION 'tenant_content_snapshot_bound_exceeded';END IF;
   row_chain:=encode(extensions.digest(row_chain||E'\n'||row_text,'sha256'),'hex');stream_buffer:=stream_buffer||row_text;
   WHILE char_length(stream_buffer)>=65536 LOOP
    IF sequence_number>=2048 THEN RAISE EXCEPTION 'tenant_content_fragment_bound_exceeded';END IF;
    RETURN NEXT jsonb_build_object('manifest',manifest->>'id','manifest_sha256',manifest->>'manifest_sha256','tenant_id',p_tenant,'table',entry->>'table','sequence',sequence_number,'table_sequence',table_sequence,'table_complete',false,'table_row_count',NULL,'table_row_chain_sha256',NULL,'json_fragment',left(stream_buffer,65536));
    stream_buffer:=substring(stream_buffer FROM 65537);sequence_number:=sequence_number+1;table_sequence:=table_sequence+1;
   END LOOP;
  END LOOP;
  -- Every table ends with an explicit completion fragment, including empty
  -- tables and exact-boundary streams. Empty fragments preserve final digests.
  IF sequence_number>=2048 THEN RAISE EXCEPTION 'tenant_content_fragment_bound_exceeded';END IF;
  RETURN NEXT jsonb_build_object('manifest',manifest->>'id','manifest_sha256',manifest->>'manifest_sha256','tenant_id',p_tenant,'table',entry->>'table','sequence',sequence_number,'table_sequence',table_sequence,'table_complete',true,'table_row_count',table_rows,'table_row_chain_sha256',row_chain,'json_fragment',stream_buffer);
  sequence_number:=sequence_number+1;
 END LOOP;
 RETURN;
END $$;
REVOKE ALL ON FUNCTION public.sandy_tenant_content_manifest_v1(),public.sandy_tenant_content_schema_sha256(),public.sandy_tenant_content_capture_v1(uuid) FROM PUBLIC,anon,authenticated,service_role;
COMMIT;
